func hostEnrollmentPublicFromRecord(record bootstrapmaterial.Record, caWire []byte, now time.Time) (hostenroll.PublicBundle, error) {
	if record.SchemaVersion != 1 || record.Config.Validate() != nil || len(record.Config.Slots) != 3 ||
		record.ExpiresAt.Sub(record.IssuedAt) != time.Duration(record.Config.ValidityHours)*time.Hour ||
		now.IsZero() || now.Add(24*time.Hour).After(record.ExpiresAt) {
		return hostenroll.PublicBundle{}, errors.New("reviewed regional material does not have a valid identity or image build window")
	}
	var caDigest string
	for _, file := range record.Files {
		if file.Name == "ca.pem" {
			if caDigest != "" || file.Purpose != bootstrap.SecretRegionalShared || file.Slot != "" || file.MaxBytes != int64(len(caWire)) {
				return hostenroll.PublicBundle{}, errors.New("reviewed regional CA file is invalid")
			}
			caDigest = file.SHA256
		}
	}
	if caDigest == "" || !matchesSHA256(caWire, caDigest) {
		return hostenroll.PublicBundle{}, errors.New("regional CA differs from reviewed material")
	}
	bundle := hostenroll.PublicBundle{SchemaVersion: 1, Cell: record.Config.Cell,
		Region: strings.ToUpper(record.Config.Cell), Environment: record.Config.Environment,
		CAPEM: string(caWire), ControllerResponsePublicKey: record.Public.ControllerResponsePublicKey,
		CellAccountNKey: record.Public.CellAccountNKey,
		InstallRoot:     hostInstallRoot, StateRoot: hostStateRoot, ManagedRuntimeRoot: hostManagedRuntimeRoot,
		WorkloadUID: hostWorkloadUID, WorkloadGID: hostWorkloadGID}
	for index, slot := range record.Config.Slots {
		if slot.Name != fmt.Sprintf("controller-%c", 'a'+index) {
			return hostenroll.PublicBundle{}, errors.New("reviewed controller slots are not in canonical order")
		}
		bundle.ControllerEndpoints = append(bundle.ControllerEndpoints, slot.PrivateIP+":8443")
		bundle.NATSURLs = append(bundle.NATSURLs, "tls://"+slot.PrivateIP+":4222")
	}
	if err := bundle.Validate(); err != nil {
		return hostenroll.PublicBundle{}, err
	}
	return bundle, nil
}

func testHostEnrollmentPublicFailures(t *testing.T, record bootstrapmaterial.Record, caWire []byte, now time.Time) {
	t.Helper()
	if _, err := hostEnrollmentPublicFromRecord(record, []byte("different CA"), now); err == nil {
		t.Fatal("unreviewed regional CA accepted")
	}
	changed := record
	changed.Files = append([]bootstrapmaterial.File(nil), record.Files...)
	for index := range changed.Files {
		if changed.Files[index].Name == "ca.pem" {
			changed.Files[index].SHA256 = strings.Repeat("0", 64)
		}
	}
	if _, err := hostEnrollmentPublicFromRecord(changed, caWire, now); err == nil {
		t.Fatal("unreviewed regional CA digest accepted")
	}
	invalidConfigs := []struct {
		name   string
		change func(*bootstrapmaterial.Config)
	}{
		{"cell region mismatch", func(config *bootstrapmaterial.Config) { config.Region = "us-sanjose-1" }},
		{"unsupported cell", func(config *bootstrapmaterial.Config) { config.Cell = "unknown" }},
		{"missing slot", func(config *bootstrapmaterial.Config) { config.Slots = config.Slots[:2] }},
		{"wrong slot order", func(config *bootstrapmaterial.Config) {
			config.Slots[0], config.Slots[1] = config.Slots[1], config.Slots[0]
		}},
		{"duplicate slot IP", func(config *bootstrapmaterial.Config) { config.Slots[1].PrivateIP = config.Slots[0].PrivateIP }},
		{"out of subnet IP", func(config *bootstrapmaterial.Config) { config.Slots[1].PrivateIP = "10.252.0.12" }},
		{"invalid validity", func(config *bootstrapmaterial.Config) { config.ValidityHours = 721 }},
	}
	for _, test := range invalidConfigs {
		t.Run(test.name, func(t *testing.T) {
			changed := record
			changed.Config.Slots = append([]bootstrapmaterial.Slot(nil), record.Config.Slots...)
			test.change(&changed.Config)
			if _, err := hostEnrollmentPublicFromRecord(changed, caWire, now); err == nil {
				t.Fatal("invalid regional material accepted")
			}
		})
	}
	changed = record
	changed.ExpiresAt = changed.ExpiresAt.Add(time.Hour)
	if _, err := hostEnrollmentPublicFromRecord(changed, caWire, now); err == nil {
		t.Fatal("material lifetime differs from reviewed validity")
	}
	if _, err := hostEnrollmentPublicFromRecord(record, caWire, now.Add(25*time.Hour)); err == nil {
		t.Fatal("image bundle emitted with less than 24 hours of material validity")
	}
	if _, err := hostEnrollmentPublicFromRecord(record, caWire, now.Add(24*time.Hour)); err != nil {
		t.Fatalf("image bundle rejected with exactly 24 hours remaining: %v", err)
	}
	changed = record
	changed.Config.Slots = append([]bootstrapmaterial.Slot(nil), record.Config.Slots...)
	changed.Config.Slots[0].PrivateIP = "10.251.0.14"
	bundle, err := hostEnrollmentPublicFromRecord(changed, caWire, now)
	if err != nil || bundle.ControllerEndpoints[0] != "10.251.0.14:8443" {
		t.Fatalf("valid reviewed controller slot did not determine endpoint: %v", err)
	}
}

func ParsePublicBundle(wire []byte) (PublicBundle, error) {
	if len(wire) == 0 || len(wire) > MaxPublicBundleBytes {
		return PublicBundle{}, errors.New("host enrollment public bundle is missing or too large")
	}
	var bundle PublicBundle
	if err := json.Unmarshal(wire, &bundle, json.RejectUnknownMembers(true)); err != nil {
		return PublicBundle{}, fmt.Errorf("parse host enrollment public bundle: %w", err)
	}
	if err := bundle.Validate(); err != nil {
		return PublicBundle{}, err
	}
	return bundle, nil
}

func (bundle PublicBundle) Validate() error {
	if bundle.SchemaVersion != 1 || !validCellRegion(bundle.Cell, bundle.Region) ||
		bundle.Environment != "canary" && bundle.Environment != "production" ||
		bundle.WorkloadUID == 0 || bundle.WorkloadGID == 0 ||
		!cleanRoot(bundle.InstallRoot) || !cleanRoot(bundle.StateRoot) || !cleanRoot(bundle.ManagedRuntimeRoot) ||
		pathsOverlap(bundle.InstallRoot, bundle.StateRoot) || pathsOverlap(bundle.InstallRoot, bundle.ManagedRuntimeRoot) ||
		pathsOverlap(bundle.StateRoot, bundle.ManagedRuntimeRoot) {
		return errors.New("host enrollment public bundle has invalid identity or local paths")
	}
	if _, err := bundle.ResponsePublicKey(); err != nil {
		return err
	}
	if !nkeys.IsValidPublicAccountKey(bundle.CellAccountNKey) {
		return errors.New("host enrollment cell account key is invalid")
	}
	if _, err := bundle.RootCAs(); err != nil {
		return err
	}
	if len(bundle.ControllerEndpoints) != 3 || len(bundle.NATSURLs) != 3 {
		return errors.New("host enrollment needs exactly three regional controller and NATS endpoints")
	}
	controllers := make([]netip.Addr, 0, 3)
	natsPeers := make([]netip.Addr, 0, 3)
	for _, endpoint := range bundle.ControllerEndpoints {
		ip, err := parseEndpoint(endpoint, "8443")
		if err != nil || slices.Contains(controllers, ip) {
			return errors.New("host enrollment controller endpoints must be distinct private IPv4 port 8443 addresses")
		}
		controllers = append(controllers, ip)
	}
	for _, raw := range bundle.NATSURLs {
		parsed, err := url.Parse(raw)
		if err != nil || parsed.Scheme != "tls" || parsed.User != nil || parsed.RawQuery != "" || parsed.Fragment != "" || parsed.Path != "" {
			return errors.New("host enrollment NATS URLs must be direct private TLS endpoints")
		}
		ip, err := parseEndpoint(parsed.Host, "4222")
		if err != nil || slices.Contains(natsPeers, ip) {
			return errors.New("host enrollment NATS endpoints must be distinct private IPv4 port 4222 addresses")
		}
		natsPeers = append(natsPeers, ip)
	}
	slices.SortFunc(controllers, netip.Addr.Compare)
	slices.SortFunc(natsPeers, netip.Addr.Compare)
	if !slices.Equal(controllers, natsPeers) {
		return errors.New("host enrollment controller and NATS endpoints differ")
	}
	return nil
}

func (bundle PublicBundle) ResponsePublicKey() (ed25519.PublicKey, error) {
	key, err := base64.StdEncoding.DecodeString(bundle.ControllerResponsePublicKey)
	if err != nil || len(key) != ed25519.PublicKeySize {
		return nil, errors.New("host enrollment response public key is invalid")
	}
	return ed25519.PublicKey(key), nil
}

func (bundle PublicBundle) RootCAs() (*x509.CertPool, error) {
	block, rest := pem.Decode([]byte(bundle.CAPEM))
	if block == nil || block.Type != "CERTIFICATE" || len(strings.TrimSpace(string(rest))) != 0 {
		return nil, errors.New("host enrollment requires one regional CA certificate")
	}
	root, err := x509.ParseCertificate(block.Bytes)
	if err != nil || !root.IsCA || root.KeyUsage&x509.KeyUsageCertSign == 0 || root.CheckSignatureFrom(root) != nil {
		return nil, errors.New("host enrollment regional CA certificate is invalid")
	}
	pool := x509.NewCertPool()
	pool.AddCert(root)
	return pool, nil
}

