func (c command) writeNew(path string, contents []byte, mode os.FileMode) error {
	if err := c.ctx.Err(); err != nil {
		return err
	}
	if path == "" || len(contents) == 0 {
		return errors.New("output path and content are required")
	}
	file, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, mode)
	if err != nil {
		return fmt.Errorf("create output without overwrite: %w", err)
	}
	if err := c.ctx.Err(); err != nil {
		_ = file.Close()
		_ = os.Remove(path)
		return err
	}
	if _, err := file.Write(contents); err != nil {
		_ = file.Close()
		_ = os.Remove(path)
		return err
	}
	if err := file.Sync(); err != nil {
		_ = file.Close()
		_ = os.Remove(path)
		return err
	}
	if err := file.Close(); err != nil {
		_ = os.Remove(path)
		return err
	}
	if err := c.ctx.Err(); err != nil {
		_ = os.Remove(path)
		return err
	}
	return nil
}

commandio.text:
func NewWriter(destination io.Writer) *Writer {
	return &Writer{destination: destination}
}

func (writer *Writer) Write(contents []byte) (int, error) {
	if writer.err != nil {
		return 0, writer.err
	}
	written, err := writer.destination.Write(contents)
	if err == nil && written != len(contents) {
		err = io.ErrShortWrite
	}
	writer.err = err
	return written, err
}

func (writer *Writer) Err() error { return writer.err }

