func (c command) verifyBootstrapAnchorAt(args []string, now time.Time) error {
	flags := flag.NewFlagSet("verify-anchor", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	anchorPath := flags.String("anchor", "", "canonical root-signed deployment bootstrap anchor envelope")
	identityPath := flags.String("identity", "", "canonical version-1 baked identity JSON")
	var rootPaths stringListFlag
	flags.Var(&rootPaths, "root-key", "trusted root Ed25519 public key PEM (repeatable)")
	if err := flags.Parse(args); err != nil {
		return err
	}
	if *anchorPath == "" || *identityPath == "" || flags.NArg() != 0 {
		return errors.New("verify-anchor requires --anchor, --identity, and at least one --root-key")
	}
	if len(rootPaths) == 0 || len(rootPaths) > bootstrapstart.MaxRootFiles {
		return fmt.Errorf("verify-anchor requires between 1 and %d --root-key files", bootstrapstart.MaxRootFiles)
	}
	verified, _, err := loadVerifiedBootstrapAnchor(*anchorPath, *identityPath, rootPaths, now)
	if err != nil {
		return err
	}
	anchor := verified.Anchor()
	grant, err := verified.LedgerDelegation()
	if err != nil {
		return err
	}
	output := verifiedBootstrapAnchorOutput{
		SchemaVersion: bootstrap.BootstrapAnchorSchemaVersion, AnchorSHA256: verified.Digest(),
		DeploymentID: anchor.DeploymentID, Environment: anchor.Environment, ClusterID: anchor.ClusterID,
		Cell: anchor.Cell, OCIRegion: anchor.OCIRegion, ControllerSlots: anchor.ControllerSlots,
		StorageDomain: anchor.StorageDomain, InitialRegionIntentGeneration: anchor.InitialRegionIntentGeneration,
		InitialRegionIntentSHA256: anchor.InitialRegionIntentSHA256, LedgerDelegationSubjectKeyID: grant.SubjectKeyID(),
		IssuedAt: verified.IssuedAt(), ExpiresAt: verified.ExpiresAt(),
	}
	encoded, err := trust.EncodePayload(output)
	if err != nil {
		return fmt.Errorf("encode verified bootstrap anchor summary: %w", err)
	}
	if _, err := c.output.Write(append(encoded, '\n')); err != nil {
		return fmt.Errorf("write verified bootstrap anchor summary: %w", err)
	}
	return nil
}

func loadVerifiedBootstrapAnchor(anchorPath, identityPath string, rootPaths []string, now time.Time) (
	bootstrap.VerifiedBootstrapAnchor, trust.Keyring, error,
) {
	identityWire, err := readBoundedRegular(identityPath, 4<<10)
	if err != nil {
		return bootstrap.VerifiedBootstrapAnchor{}, trust.Keyring{}, fmt.Errorf("read fixed bootstrap identity: %w", err)
	}
	var identity bootstrapstart.BakedIdentity
	if err := protocol.DecodeStrict(identityWire, &identity, 4<<10); err != nil {
		return bootstrap.VerifiedBootstrapAnchor{}, trust.Keyring{}, fmt.Errorf("decode fixed bootstrap identity: %w", err)
	}
	if identity.SchemaVersion != 1 {
		return bootstrap.VerifiedBootstrapAnchor{}, trust.Keyring{}, errors.New("fixed bootstrap identity schemaVersion must be 1")
	}
	canonical, err := protocol.EncodeJSON(identity)
	if err != nil || !bytes.Equal(identityWire, canonical) {
		return bootstrap.VerifiedBootstrapAnchor{}, trust.Keyring{}, errors.New("fixed bootstrap identity must be canonical JSON")
	}
	expected := identity.AnchorExpectation()
	rootKeys := make([]ed25519.PublicKey, 0, len(rootPaths))
	rootBytes := 0
	for _, path := range rootPaths {
		wire, err := readBoundedRegular(path, bootstrapstart.MaxRootBytes)
		if err != nil {
			return bootstrap.VerifiedBootstrapAnchor{}, trust.Keyring{}, err
		}
		rootBytes += len(wire)
		if rootBytes > bootstrapstart.MaxRootsTotal {
			return bootstrap.VerifiedBootstrapAnchor{}, trust.Keyring{}, fmt.Errorf("bootstrap root key files exceed %d aggregate bytes", bootstrapstart.MaxRootsTotal)
		}
		publicKey, err := parseRootPublicKey(wire)
		if err != nil {
			return bootstrap.VerifiedBootstrapAnchor{}, trust.Keyring{}, err
		}
		rootKeys = append(rootKeys, publicKey)
	}
	roots, err := trust.ParseKeyring(rootKeys...)
	if err != nil {
		return bootstrap.VerifiedBootstrapAnchor{}, trust.Keyring{}, fmt.Errorf("parse root trust set: %w", err)
	}
	anchorWire, err := readBoundedRegular(anchorPath, bootstrap.MaxBootstrapAnchorBytes)
	if err != nil {
		return bootstrap.VerifiedBootstrapAnchor{}, trust.Keyring{}, fmt.Errorf("read bootstrap anchor: %w", err)
	}
	envelope, err := trust.DecodeEnvelope(anchorWire)
	if err != nil {
		return bootstrap.VerifiedBootstrapAnchor{}, trust.Keyring{}, fmt.Errorf("decode bootstrap anchor: %w", err)
	}
	now = now.Round(0).UTC()
	verified, err := bootstrap.VerifyBootstrapAnchor(envelope, roots, expected, now, bootstrap.BootstrapAnchorTrustPolicy())
	if err != nil {
		return bootstrap.VerifiedBootstrapAnchor{}, trust.Keyring{}, fmt.Errorf("verify current bootstrap anchor: %w", err)
	}
	return verified, roots, nil
}

retirement.text:
func (c command) signSlotRetirementAt(args []string, now time.Time) error {
	flags := flag.NewFlagSet("sign-slot-retirement", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	candidatePath := flags.String("candidate", "", "controller-rendered <slot>.retirement-request.json")
	slot := flags.String("slot", "", "controller slot being retired, restated by the operator")
	attempt := flags.Uint64("attempt", 0, "ledger attempt being retired, restated by the operator")
	instance := flags.String("instance", "", "retired instance OCID, independently confirmed TERMINATED")
	publicPath := flags.String("root-key", "", "offline root public key PEM")
	privatePath := flags.String("signing-key", "", "owner-only offline root private key PEM")
	outputPath := flags.String("out", "", "new signed <slot>.retirement envelope")
	validFor := flags.Duration("valid-for", time.Hour, "retirement validity; at most 24h")
	if err := flags.Parse(args); err != nil {
		return err
	}
	if *candidatePath == "" || *slot == "" || *attempt == 0 || *instance == "" || *publicPath == "" ||
		*privatePath == "" || *outputPath == "" || flags.NArg() != 0 {
		return errors.New("sign-slot-retirement requires --candidate, --slot, --attempt, --instance, --root-key, --signing-key, and --out")
	}
	now = now.Round(0).UTC()
	if now.IsZero() || *validFor <= 0 || *validFor > bootstrap.MaxSlotRetirementLifetime {
		return errors.New("retirement signing time or validity is invalid")
	}
	wire, err := c.readBoundedRegular(*candidatePath, 16<<10)
	if err != nil {
		return err
	}
	var candidate bootstrap.RetirementEvidence
	if err := protocol.DecodeStrict(wire, &candidate, 16<<10); err != nil {
		return err
	}
	canonical, err := protocol.EncodeJSON(candidate)
	if err != nil || !bytes.Equal(wire, canonical) {
		return errors.New("retirement candidate must be canonical JSON")
	}
	if err := bootstrap.ValidateSlotRetirementCandidate(candidate); err != nil {
		return err
	}
	if candidate.Slot != *slot || candidate.PreviousAttempt != *attempt || candidate.PriorInstanceOCID != *instance {
		return errors.New("retirement candidate differs from the operator-confirmed slot, attempt, or instance")
	}
	if now.Sub(candidate.ObservedAt) > bootstrap.MaxSlotRetirementLifetime {
		return errors.New("retirement candidate observation is stale; let the controller render a fresh request")
	}
	public, err := readRootPublicKey(*publicPath)
	if err != nil {
		return err
	}
	private, err := readRootPrivateKey(*privatePath)
	if err != nil {
		return err
	}
	defer clear(private)
	if !bytes.Equal(private.Public().(ed25519.PublicKey), public) {
		return errors.New("root signing key does not match public key")
	}
	signed, err := bootstrap.SignSlotRetirement(candidate, now, now.Add(*validFor), private)
	if err != nil {
		return err
	}
	encoded, err := trust.EncodeEnvelope(signed)
	if err != nil {
		return err
	}
	if err := c.writeNew(*outputPath, encoded, 0o600); err != nil {
		return err
	}
	fmt.Fprintf(c.output, "signed slot retirement slot=%s attempt=%d instance=%s digest=%x expires=%s\n",
		candidate.Slot, candidate.PreviousAttempt, candidate.PriorInstanceOCID, sha256.Sum256(encoded),
		now.Add(*validFor).Format(time.RFC3339))
	return nil
}

anchor.text:
func (scope FoundationScope) Validate() error {
	if !entityid.Valid(scope.InstallationID) || !entityid.Valid(scope.DeploymentID) || !entityid.Valid(scope.ClusterID) ||
		!isOCID(scope.TenancyID, "tenancy") || scope.OCIRegion != "sa-saopaulo-1" || scope.GrantGeneration == 0 || !sha256RE.MatchString(scope.GrantSHA256) {
		return fmt.Errorf("%w: invalid home foundation discovery reference", ErrBootstrapAnchorInvalid)
	}
	if err := scope.StorageDomain.Validate(); err != nil {
		return fmt.Errorf("%w: invalid home foundation storage: %v", ErrBootstrapAnchorInvalid, err)
	}
	for _, key := range []string{scope.StorageDomain.HeadKMSKeyOCID, scope.StorageDomain.LedgerKMSKeyOCID} {
		if !strings.HasPrefix(key, "ocid1.key.oc1.sa-saopaulo-1.") {
			return fmt.Errorf("%w: home foundation KMS region differs", ErrBootstrapAnchorInvalid)
		}
	}
	return nil
}

// Validate verifies the immutable deployment scope, complete ledger domain,
// canonical intent bytes, and redundant generation and digest pins.
func (anchor BootstrapAnchor) Validate() error {
	ociRegion, err := anchor.Cell.OCIRegion()
	if err != nil || anchor.SchemaVersion != BootstrapAnchorSchemaVersion ||
		!entityid.Valid(anchor.DeploymentID) || !entityid.Valid(anchor.ClusterID) ||
		(anchor.Environment != "production" && anchor.Environment != "canary") || anchor.OCIRegion != ociRegion {
		return fmt.Errorf("%w: required identity or region binding", ErrBootstrapAnchorInvalid)
	}
	if anchor.FoundationScope != nil {
		if err := anchor.FoundationScope.Validate(); err != nil {
			return err
		}
		if anchor.Cell == "GRU" && (anchor.FoundationScope.DeploymentID != anchor.DeploymentID || anchor.FoundationScope.ClusterID != anchor.ClusterID || anchor.FoundationScope.StorageDomain != anchor.StorageDomain) {
			return fmt.Errorf("%w: home discovery identity differs from home anchor", ErrBootstrapAnchorInvalid)
		}
	}
	if err := anchor.StorageDomain.Validate(); err != nil {
		return fmt.Errorf("%w: %v", ErrBootstrapAnchorInvalid, err)
	}
	if len(anchor.ControllerSlots) == 0 || len(anchor.ControllerSlots) > MaxBootstrapAnchorSlots ||
		hasDuplicate(anchor.ControllerSlots) || !slices.IsSorted(anchor.ControllerSlots) {
		return fmt.Errorf("%w: controller slot set is absent, oversized, duplicated, or not sorted", ErrBootstrapAnchorInvalid)
	}
	for _, slot := range anchor.ControllerSlots {
		if !controllerSlotRE.MatchString(slot) {
			return fmt.Errorf("%w: invalid controller slot %q", ErrBootstrapAnchorInvalid, slot)
		}
	}
	if anchor.InitialSourceRegistration != nil {
		registration := anchor.InitialSourceRegistration
		if len(anchor.LedgerDelegationWire) != 0 || anchor.FoundationScope == nil || registration.Validate() != nil || registration.DeploymentID != anchor.DeploymentID || registration.Environment != anchor.Environment || registration.ClusterID != anchor.ClusterID || registration.Cell != anchor.Cell || registration.Generation != anchor.FoundationScope.GrantGeneration || registration.InstallationID != anchor.FoundationScope.InstallationID || registration.StorageDomain != anchor.StorageDomain || !slices.Equal(registration.ControllerSlots, anchor.ControllerSlots) {
			return fmt.Errorf("%w: source registration differs from exact anchor or replaces pinned ledger signer", ErrBootstrapAnchorInvalid)
		}
	} else {
		if len(anchor.LedgerDelegationWire) == 0 || len(anchor.LedgerDelegationWire) > MaxBootstrapLedgerGrantBytes {
			return fmt.Errorf("%w: ledger delegation wire is absent or exceeds %d bytes", ErrBootstrapAnchorInvalid, MaxBootstrapLedgerGrantBytes)
		}
		grantEnvelope, err := trust.DecodeEnvelope(anchor.LedgerDelegationWire)
		if err != nil {
			return fmt.Errorf("%w: decode ledger delegation wire: %v", ErrBootstrapAnchorInvalid, err)
		}
		grant, err := decodeBootstrapLedgerDelegation(grantEnvelope)
		if err != nil {
			return err
		}
		if err := validateBootstrapLedgerCapabilities(grant, anchor); err != nil {
			return err
		}
	}
	if len(anchor.InitialRegionIntentWire) == 0 || len(anchor.InitialRegionIntentWire) > MaxInitialRegionIntentBytes ||
		anchor.InitialRegionIntentGeneration == 0 || !sha256RE.MatchString(anchor.InitialRegionIntentSHA256) {
		return fmt.Errorf("%w: initial region intent is absent or exceeds its size bound", ErrBootstrapAnchorInvalid)
	}
	intent, err := canonicalRegionIntent(anchor.InitialRegionIntentWire)
	if err != nil {
		return fmt.Errorf("%w: %v", ErrBootstrapAnchorInvalid, err)
	}
	if intent.Generation != anchor.InitialRegionIntentGeneration || digestBytes(anchor.InitialRegionIntentWire) != anchor.InitialRegionIntentSHA256 {
		return fmt.Errorf("%w: initial region-intent generation or exact-wire digest does not match", ErrBootstrapAnchorInvalid)
	}
	if !slices.ContainsFunc(intent.Regions, func(mapping oci.RegionMapping) bool {
		return mapping.Cell == anchor.Cell && mapping.OCIRegion == anchor.OCIRegion
	}) {
		return fmt.Errorf("%w: initial region intent does not admit anchor cell", ErrBootstrapAnchorInvalid)
	}
	payload, err := trust.EncodePayload(anchor)
	if err != nil {
		return fmt.Errorf("%w: encode anchor: %v", ErrBootstrapAnchorInvalid, err)
	}
	if len(payload) > MaxBootstrapAnchorBytes {
		return fmt.Errorf("%w: anchor exceeds %d bytes", ErrBootstrapAnchorInvalid, MaxBootstrapAnchorBytes)
	}
	return nil
}

func (verified VerifiedBootstrapAnchor) Anchor() BootstrapAnchor {
	return cloneBootstrapAnchor(verified.anchor)
}

// InitialRegionIntent returns the validated region authorization pinned by the
// root-signed anchor.
func (verified VerifiedBootstrapAnchor) InitialRegionIntent() oci.RegionIntent {
	intent := verified.intent
	intent.Regions = slices.Clone(verified.intent.Regions)
	return intent
}

// StorageDomain returns the root-authorized immutable ledger and CAS-head
// storage domain.
func (verified VerifiedBootstrapAnchor) StorageDomain() StorageDomain {
	return verified.anchor.StorageDomain
}

// FoundationScope returns a defensive copy of the authenticated home reference.
// Historical anchors without one retain historical validity but grant no cold
// generation authority.
func (verified VerifiedBootstrapAnchor) FoundationScope() (FoundationScope, error) {
	if !verified.verified || verified.anchor.FoundationScope == nil {
		return FoundationScope{}, fmt.Errorf("%w: home foundation reference is absent", ErrBootstrapAnchorInvalid)
	}
	return *verified.anchor.FoundationScope, nil
}

func (verified VerifiedBootstrapAnchor) LedgerDelegation() (trust.VerifiedDelegation, error) {
	if !verified.verified || len(verified.anchor.LedgerDelegationWire) == 0 {
		return trust.VerifiedDelegation{}, fmt.Errorf("%w: anchor verification is absent", ErrBootstrapAnchorInvalid)
	}
	return verified.ledgerDelegation, nil
}

func SignBootstrapAnchor(anchor BootstrapAnchor, issuedAt, expiresAt time.Time, rootPrivateKey ed25519.PrivateKey) (trust.Envelope, error) {
	if anchor.SchemaVersion != BootstrapAnchorSchemaVersion {
		return trust.Envelope{}, fmt.Errorf("%w: new anchors must use schema version %d", ErrBootstrapAnchorInvalid, BootstrapAnchorSchemaVersion)
	}
	if err := anchor.Validate(); err != nil {
		return trust.Envelope{}, err
	}
	if len(anchor.LedgerDelegationWire) > 0 {
		grantEnvelope, err := trust.DecodeEnvelope(anchor.LedgerDelegationWire)
		if err != nil {
			return trust.Envelope{}, fmt.Errorf("decode bootstrap ledger delegation: %w", err)
		}
		if err := validateBootstrapAnchorGrantInterval(issuedAt, expiresAt, grantEnvelope); err != nil {
			return trust.Envelope{}, err
		}
	}
	payload, err := trust.EncodePayload(anchor)
	if err != nil {
		return trust.Envelope{}, fmt.Errorf("encode bootstrap anchor: %w", err)
	}
	if len(payload) > MaxBootstrapAnchorBytes {
		return trust.Envelope{}, fmt.Errorf("%w: anchor exceeds %d bytes", ErrBootstrapAnchorInvalid, MaxBootstrapAnchorBytes)
	}
	envelope, err := trust.Sign(payload, bootstrapAnchorScope(anchor.DeploymentID, string(anchor.Cell), anchor.Environment),
		issuedAt, expiresAt, rootPrivateKey)
	if err != nil {
		return trust.Envelope{}, err
	}
	if envelope.ExpiresAt.Sub(envelope.IssuedAt) > MaxBootstrapAnchorLifetime {
		return trust.Envelope{}, fmt.Errorf("%w: anchor validity exceeds %s", ErrBootstrapAnchorInvalid, MaxBootstrapAnchorLifetime)
	}
	if err := validateBootstrapAnchorEnvelopeSize(envelope); err != nil {
		return trust.Envelope{}, err
	}
	return envelope, nil
}

// VerifyBootstrapAnchor verifies the root signature before exposing any
// cluster, storage, or initial region-intent facts.
func VerifyBootstrapAnchor(envelope trust.Envelope, roots trust.Keyring, expected BootstrapAnchorExpectation,
	now time.Time, policy trust.Policy,
) (VerifiedBootstrapAnchor, error) {
	return verifyBootstrapAnchor(envelope, roots, expected, now, policy, false, time.Time{})
}

func verifyBootstrapAnchor(envelope trust.Envelope, roots trust.Keyring, expected BootstrapAnchorExpectation,
	now time.Time, policy trust.Policy, historical bool, acceptedAt time.Time,
) (VerifiedBootstrapAnchor, error) {
	if policy.MaxLifetime <= 0 || policy.MaxLifetime > MaxBootstrapAnchorLifetime || policy.ClockSkew < 0 ||
		envelope.ExpiresAt.Sub(envelope.IssuedAt) > MaxBootstrapAnchorLifetime {
		return VerifiedBootstrapAnchor{}, fmt.Errorf("%w: invalid or overlong anchor verification policy", ErrBootstrapAnchorInvalid)
	}
	if err := validateBootstrapAnchorEnvelopeSize(envelope); err != nil {
		return VerifiedBootstrapAnchor{}, err
	}
	if err := expected.validate(); err != nil {
		return VerifiedBootstrapAnchor{}, err
	}
	scope := bootstrapAnchorScope(expected.DeploymentID, string(expected.Cell), expected.Environment)
	var payload []byte
	var err error
	if historical {
		payload, err = trust.VerifyHistorical(envelope, scope, roots, policy)
		if err == nil {
			acceptedAt = acceptedAt.Round(0).UTC()
			if acceptedAt.IsZero() || acceptedAt.Year() < 1 || acceptedAt.Year() > 9999 ||
				acceptedAt.Sub(envelope.IssuedAt) < -policy.ClockSkew || !acceptedAt.Before(envelope.ExpiresAt) {
				err = fmt.Errorf("%w: anchor did not cover accepted installation time", ErrBootstrapAnchorInvalid)
			}
		}
	} else {
		payload, err = trust.VerifyCurrent(envelope, scope, roots, now, policy)
	}
	if err != nil {
		return VerifiedBootstrapAnchor{}, fmt.Errorf("verify bootstrap anchor signature: %w", err)
	}
	if len(payload) > MaxBootstrapAnchorBytes {
		return VerifiedBootstrapAnchor{}, fmt.Errorf("%w: anchor exceeds %d bytes", ErrBootstrapAnchorInvalid, MaxBootstrapAnchorBytes)
	}
	var anchor BootstrapAnchor
	if err := protocol.DecodeStrict(payload, &anchor, MaxBootstrapAnchorBytes); err != nil {
		return VerifiedBootstrapAnchor{}, fmt.Errorf("decode bootstrap anchor: %w", err)
	}
	if err := anchor.Validate(); err != nil {
		return VerifiedBootstrapAnchor{}, err
	}
	if anchor.DeploymentID != expected.DeploymentID || anchor.Environment != expected.Environment || anchor.Cell != expected.Cell {
		return VerifiedBootstrapAnchor{}, fmt.Errorf("%w: anchor does not match fixed local boot identity", ErrBootstrapAnchorInvalid)
	}
	var ledgerDelegation trust.VerifiedDelegation
	if len(anchor.LedgerDelegationWire) > 0 {
		grantEnvelope, err := trust.DecodeEnvelope(anchor.LedgerDelegationWire)
		if err != nil {
			return VerifiedBootstrapAnchor{}, fmt.Errorf("%w: decode ledger delegation wire: %v", ErrBootstrapAnchorInvalid, err)
		}
		if historical {
			ledgerDelegation, err = trust.VerifyDelegationHistorical(grantEnvelope, roots, policy)
		} else {
			ledgerDelegation, err = trust.VerifyDelegationCurrent(grantEnvelope, roots, now, policy)
		}
		if err != nil {
			return VerifiedBootstrapAnchor{}, fmt.Errorf("verify bootstrap ledger delegation: %w", err)
		}
		if err := validateBootstrapAnchorGrantInterval(envelope.IssuedAt, envelope.ExpiresAt, grantEnvelope); err != nil {
			return VerifiedBootstrapAnchor{}, err
		}
		if err := validateVerifiedBootstrapLedgerCapabilities(ledgerDelegation, anchor); err != nil {
			return VerifiedBootstrapAnchor{}, err
		}
	}
	intent, err := canonicalRegionIntent(anchor.InitialRegionIntentWire)
	if err != nil {
		return VerifiedBootstrapAnchor{}, fmt.Errorf("%w: %v", ErrBootstrapAnchorInvalid, err)
	}
	wire, err := trust.EncodeEnvelope(envelope)
	if err != nil {
		return VerifiedBootstrapAnchor{}, fmt.Errorf("%w: encode verified envelope: %v", ErrBootstrapAnchorInvalid, err)
	}
	digest, err := trust.Fingerprint(envelope)
	if err != nil {
		return VerifiedBootstrapAnchor{}, err
	}
	return VerifiedBootstrapAnchor{
		anchor: cloneBootstrapAnchor(anchor), intent: cloneRegionIntent(intent), ledgerDelegation: ledgerDelegation,
		wire: bytes.Clone(wire), digest: digest, issuedAt: envelope.IssuedAt,
		expiresAt: envelope.ExpiresAt, verified: true,
	}, nil
}

func cloneBootstrapAnchor(anchor BootstrapAnchor) BootstrapAnchor {
	if anchor.InitialSourceRegistration != nil {
		anchor.InitialSourceRegistration = new(anchor.InitialSourceRegistration.Clone())
	}
	if anchor.FoundationScope != nil {
		anchor.FoundationScope = new(*anchor.FoundationScope)
	}
	anchor.ControllerSlots = slices.Clone(anchor.ControllerSlots)
	anchor.LedgerDelegationWire = bytes.Clone(anchor.LedgerDelegationWire)
	anchor.InitialRegionIntentWire = bytes.Clone(anchor.InitialRegionIntentWire)
	return anchor
}

